import{_ as o,a0 as n,w as l,s as p,I as s,x as e,a1 as t,A as a,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"如何在 Linux 系統中使用 dd 命令而不會損毀你的磁盤 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 系統中使用 dd 命令而不會損毀你的磁盤 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 系統中使用 dd 命令而不會損毀你的磁盤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 系統中使用 dd 命令而不會損毀你的磁盤 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20180705 How to use dd in Linux without destroying your disk","title":"如何在 Linux 系統中使用 dd 命令而不會損毀你的磁盤","tag":"201807","desc":""},"relativePath":"201807/20180705 How to use dd in Linux without destroying your disk.md","filePath":"[post].md"}'),u={name:"201807/20180705 How to use dd in Linux without destroying your disk.md"};function h(g,d,c,k,b,f){const i=n("Link");return l(),p("div",null,[d[18]||(d[18]=s("h1",{id:"如何在-linux-系統中使用-dd-命令而不會損毀你的磁盤",tabindex:"-1"},[e("如何在 Linux 系統中使用 dd 命令而不會損毀你的磁盤 "),s("a",{class:"header-anchor",href:"#如何在-linux-系統中使用-dd-命令而不會損毀你的磁盤","aria-label":"Permalink to “如何在 Linux 系統中使用 dd 命令而不會損毀你的磁盤”"},"​")],-1)),d[19]||(d[19]=s("blockquote",null,[s("p",null,"使用 Linux 中的 dd 工具安全、可靠地製作一個驅動器、分區和文件系統的完整鏡像。")],-1)),d[20]||(d[20]=s("p",null,[s("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/computer_happy_sad_developer_programming.png?itok=72nkfSQ_",alt:""})],-1)),s("p",null,[s("em",null,[d[1]||(d[1]=e("這篇文章節選自 Manning 出版社出版的圖書 ",-1)),t(i,{href:"https://www.manning.com/books/linux-in-action?a_aid=bootstrap-it&a_bid=4ca15fc9&chan=opensource"},{default:a(()=>[...d[0]||(d[0]=[e("Linux in Action",-1)])]),_:1}),d[2]||(d[2]=e("的第 4 章。",-1))])]),d[21]||(d[21]=r(`<p>你是否正在從一個即將損壞的存儲驅動器挽救數據，或者要把本地歸檔進行遠程備份，或者要把一個別處的活動分區做個完整的副本，那麼你需要懂得如何安全而可靠的複製驅動器和文件系統。幸運的是，<code>dd</code> 是一個可以使用的簡單而又功能強大的鏡像複製命令，從現在到未來很長的時間內，也許直到永遠都不會出現比 <code>dd</code> 更好的工具了。</p><h3 id="對驅動器和分區做個完整的副本" tabindex="-1">對驅動器和分區做個完整的副本 <a class="header-anchor" href="#對驅動器和分區做個完整的副本" aria-label="Permalink to “對驅動器和分區做個完整的副本”">​</a></h3><p>仔細研究後，你會發現你可以使用 <code>dd</code> 做各種任務，但是它最重要的功能是處理磁盤分區。當然，你可以使用 <code>tar</code> 命令或者 <code>scp</code> 命令從一台計算機複製整個文件系統的文件，然後把這些文件原樣粘貼在另一台剛剛安裝好 Linux 操作系統的計算機中。但是，因為那些文件系統歸檔不是完整的映像文件，所以在複製文件的過程中需要計算機操作系統的運行作為基礎。</p><p>另一方面，使用 <code>dd</code> 可以對任何數字信息完美的進行逐個字節的鏡像。但是不論何時何地，當你要對分區進行操作時，我要告訴你早期的 Unix 管理員曾開過這樣的玩笑：“ dd 的意思是<ruby>磁盤毀滅者<rt>disk destroyer</rt></ruby>”（LCTT 譯註：<code>dd</code> 原意是<ruby>磁盤複製<rt>disk dump</rt></ruby>）。 在使用 <code>dd</code> 命令的時候，如果你輸入了哪怕是一個字母，也可能立即永久性的擦除掉整個磁盤驅動器裏的所有重要的數據。因此，一定要注意命令的拼寫格式規範。</p><p><strong>記住：</strong> 在按下回車鍵執行 <code>dd</code> 命令之前，暫時停下來仔細的認真思考一下。</p><h3 id="dd-命令的基本操作" tabindex="-1">dd 命令的基本操作 <a class="header-anchor" href="#dd-命令的基本操作" aria-label="Permalink to “dd 命令的基本操作”">​</a></h3><p>現在你已經得到了適當的提醒，我們將從簡單的事情開始。假設你要對代號為 <code>/dev/sda</code> 的整個磁盤數據創建精確的映像，你已經插入了一塊空的磁盤驅動器 （理想情況下具有與代號為 <code>/dev/sda</code> 的磁盤驅動器相同的容量）。語法很簡單： <code>if=</code> 定義源驅動器，<code>of=</code> 定義你要將數據保存到的文件或位置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dd if=/dev/sda of=/dev/sdb</span></span></code></pre></div><p>接下來的例子將要對 <code>/dev/sda</code> 驅動器創建一個 .img 的映像文件，然後把該文件保存的你的用户帳號家目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dd if=/dev/sda of=/home/username/sdadisk.img</span></span></code></pre></div><p>上面的命令針對整個驅動器創建映像文件，你也可以針對驅動器上的單個分區進行操作。下面的例子針對驅動器的單個分區進行操作，同時使用了一個 <code>bs</code> 參數用於設置單次拷貝的字節數量 （此例中是 4096）。設定 <code>bs</code> 參數值可能會影響 <code>dd</code> 命令的整體操作速度，該參數的理想設置取決於你的硬件配置和其它考慮。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dd if=/dev/sda2 of=/home/username/partition2.img bs=4096</span></span></code></pre></div><p>數據的恢復非常簡單：通過顛倒 <code>if</code> 和 <code>of</code> 參數可以有效的完成任務。在此例中，<code>if=</code> 使用你要恢復的映像，<code>of=</code> 使用你想要寫入映像的目標驅動器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dd if=sdadisk.img of=/dev/sdb</span></span></code></pre></div><p>你也可以在一條命令中同時完成創建和拷貝任務。下面的例子中將使用 SSH 從遠程驅動器創建一個壓縮的映像文件，並把該文件保存到你的本地計算機中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ssh username@54.98.132.10 &quot;dd if=/dev/sda | gzip -1 -&quot; | dd of=backup.gz</span></span></code></pre></div><p>你應該經常測試你的歸檔，確保它們可正常使用。如果它是你創建的啓動驅動器，將它粘貼到計算機中，看看它是否能夠按預期啓動。如果它是普通分區的數據，掛載該分區，確保文件都存在而且可以正常的訪問。</p><h3 id="使用-dd-擦除磁盤數據" tabindex="-1">使用 dd 擦除磁盤數據 <a class="header-anchor" href="#使用-dd-擦除磁盤數據" aria-label="Permalink to “使用 dd 擦除磁盤數據”">​</a></h3><p>多年以前，我的一個負責政府海外大使館安全的朋友曾經告訴我，在他當時在任的時候， 政府會給每一個大使館提供一個官方版的錘子。為什麼呢？ 一旦大使館設施可能被不友善的人員侵佔，就會使用這個錘子毀壞所有的硬盤.</p><p>為什麼要那樣做？為什麼不是刪除數據就好了？你在開玩笑，對吧？所有人都知道從存儲設備中刪除包含敏感信息的文件實際上並沒有真正移除這些數據。除非使用錘子徹底的毀壞這些存儲介質，否則，只要有足夠的時間和動機, 幾乎所有的內容都可以從幾乎任何數字存儲介質重新獲取。</p><p>但是，你可以使用 <code>dd</code> 命令讓壞人非常難以獲得你的舊數據。這個命令需要花費一些時間在 <code>/dev/sda1</code> 分區的每個扇區寫入數百萬個 <code>0</code>（LCTT 譯註：是指 0x0 字節，意即 NUL ，而不是數字 0 ）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dd if=/dev/zero of=/dev/sda1</span></span></code></pre></div><p>還有更好的方法。通過使用 <code>/dev/urandom</code> 作為源文件，你可以在磁盤上寫入隨機字符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dd if=/dev/urandom of=/dev/sda1</span></span></code></pre></div><h3 id="監控-dd-的操作" tabindex="-1">監控 dd 的操作 <a class="header-anchor" href="#監控-dd-的操作" aria-label="Permalink to “監控 dd 的操作”">​</a></h3><p>由於磁盤或磁盤分區的歸檔可能需要很長的時間，因此你可能需要在命令中添加進度查看器。安裝管道查看器（在 Ubuntu 系統上安裝命令為 <code>sudo apt install pv</code>），然後把 <code>pv</code> 命令和 <code>dd</code> 命令結合在一起。使用 <code>pv</code>，最終的命令是這樣的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dd if=/dev/urandom | pv | dd of=/dev/sda1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4,14MB 0:00:05 [ 98kB/s] [      &lt;=&gt;                  ]</span></span></code></pre></div><p>想要推遲備份和磁盤管理工作？有了 <code>dd</code> 工具，你不會有太多的藉口。它真的非常簡單，但是要小心。祝你好運！</p><hr>`,29)),s("p",null,[d[4]||(d[4]=e("via：",-1)),t(i,{href:"https://opensource.com/article/18/7/how-use-dd-linux"},{default:a(()=>[...d[3]||(d[3]=[e("https://opensource.com/article/18/7/how-use-dd-linux",-1)])]),_:1})]),s("p",null,[d[9]||(d[9]=e("作者：",-1)),t(i,{href:"https://opensource.com/users/remyd"},{default:a(()=>[...d[5]||(d[5]=[e("David Clinton",-1)])]),_:1}),d[10]||(d[10]=e(" 選題：",-1)),t(i,{href:"https://github.com/lujun9972"},{default:a(()=>[...d[6]||(d[6]=[e("lujun9972",-1)])]),_:1}),d[11]||(d[11]=e(" 譯者：",-1)),t(i,{href:"https://github.com/SunWave"},{default:a(()=>[...d[7]||(d[7]=[e("SunWave",-1)])]),_:1}),d[12]||(d[12]=e(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:a(()=>[...d[8]||(d[8]=[e("wxy",-1)])]),_:1})]),s("p",null,[d[15]||(d[15]=e("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...d[13]||(d[13]=[e("LCTT",-1)])]),_:1}),d[16]||(d[16]=e(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:a(()=>[...d[14]||(d[14]=[e("Linux中國",-1)])]),_:1}),d[17]||(d[17]=e(" 榮譽推出",-1))])])}const y=o(u,[["render",h]]);export{v as __pageData,y as default};
